import { motion } from "framer-motion";

const environments = [
  {
    title: "Gym Interior",
    caption: "Clean interiors designed for focused training",
    img: "https://images.unsplash.com/photo-1576678927484-cc907957088c?auto=format&fit=crop&w=1200&q=80",
  },
  {
    title: "Training Zones",
    caption: "Professional-grade equipment for structured workouts",
    img: "https://images.unsplash.com/photo-1584467735871-bc8f6f6b4e63?auto=format&fit=crop&w=900&q=80",
  },
  {
    title: "Workout Floor",
    caption: "Spacious layouts supporting safe and efficient movement",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e?auto=format&fit=crop&w=900&q=80",
  },
  {
    title: "Cleanliness & Ambience",
    caption: "Well-maintained spaces promoting comfort and consistency",
    img: "https://images.unsplash.com/photo-1558611848-73f7eb4001a1?auto=format&fit=crop&w=800&q=80",
  },
];

export default function TrainingEnvironment() {
  return (
    <section className="bg-black text-white py-32 px-6">
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          viewport={{ once: true }}
          className="text-center max-w-3xl mx-auto"
        >
          <h2 className="text-4xl md:text-5xl font-bold">
            Training <span className="text-red-600">Environment</span>
          </h2>
          <p className="mt-6 text-gray-400 leading-relaxed">
            Bodyzeal Fitworks gyms are designed to support focused training with
            disciplined layouts, clean workout spaces, and a consistent
            atmosphere that encourages long-term progress.
          </p>
        </motion.div>

        {/* IMAGE CARDS */}
        <div className="mt-20 grid sm:grid-cols-2 lg:grid-cols-4 gap-10">
          {environments.map((item, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 60 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.7, delay: i * 0.15 }}
              animate={{ y: [0, -10, 0] }}
              className="relative h-[320px] rounded-2xl overflow-hidden border border-white/10 shadow-xl"
              style={{
                animationDuration: `${6 + i}s`,
                animationIterationCount: "infinite",
              }}
            >
              {/* IMAGE */}
              <img
                src={item.img}
                alt={item.title}
                className="absolute inset-0 w-full h-full object-cover"
              />

              {/* OVERLAY */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent" />

              {/* TEXT */}
              <div className="absolute bottom-0 p-5 z-10">
                <h4 className="text-lg font-semibold">{item.title}</h4>
                <p className="mt-1 text-sm text-gray-300">
                  {item.caption}
                </p>
              </div>
            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
}
